// Resolve which NPC to talk to. The chat page (npc-chat.html) passes the NPC id
// as metadata.npcId (pulled from the ?npcId= querystring), which is the normal path.
// As a convenience for the built-in n8n test window - which cannot send metadata -
// we also accept a GUID typed inline in the message, e.g. "npcId: <guid> hello".

const trigger = $input.first().json;
const meta = trigger.metadata || {};
let npcId = (meta.npcId || '').toString().trim();
let userMessage = (trigger.chatInput || '').toString();

const GUID_RE = /[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}/;

if (!npcId) {
  const m = userMessage.match(GUID_RE);
  if (m) {
    npcId = m[0];
    userMessage = userMessage.replace(/npc\s*id\s*[:=]?/i, '').replace(m[0], '').trim();
  }
}

if (!npcId) {
  throw new Error('No NPC id provided. Open the chat with ?npcId=<guid>, or include an NPC GUID in your first message (e.g. "npcId: <guid> hello").');
}
if (!GUID_RE.test(npcId)) {
  throw new Error(`"${npcId}" is not a valid NPC GUID.`);
}

return [{ json: { npcId, userMessage, sessionId: trigger.sessionId } }];

// Build a system prompt that puts the LLM "in character" as this specific NPC.
// The GHOSTS API returns an NpcRecord with a nested NpcProfile. Casing can be
// camelCase or PascalCase depending on serializer, so we look up defensively.
function pick(obj, ...keys) {
  if (!obj || typeof obj !== 'object') return undefined;
  for (const k of keys) {
    if (obj[k] !== undefined && obj[k] !== null) return obj[k];
    const lc = k.charAt(0).toLowerCase() + k.slice(1);
    if (obj[lc] !== undefined && obj[lc] !== null) return obj[lc];
  }
  return undefined;
}

const record = $input.first().json;
const p = pick(record, 'NpcProfile') || record;

if (!p || (typeof p === 'object' && !pick(p, 'Name'))) {
  throw new Error('No NPC persona returned from the GHOSTS API for this id. Check the NPC exists and that Get NPC succeeded.');
}

const name = pick(p, 'Name') || {};
const full = [pick(name, 'First'), pick(name, 'Middle'), pick(name, 'Last')].filter(Boolean).join(' ').trim() || 'this person';

const emp = pick(p, 'Employment') || {};
const edu = pick(p, 'Education') || {};
const rank = pick(p, 'Rank') || {};
const unit = pick(p, 'Unit') || {};
const mental = pick(p, 'MentalHealth') || {};
const motiv = pick(p, 'MotivationalProfile') || {};
const addrList = pick(p, 'Address') || [];
const addr = Array.isArray(addrList) ? (addrList[0] || {}) : {};

const lines = [];
lines.push(`You are ${full}. You must stay fully in character as this person for the entire conversation. Never say or imply that you are an AI, a language model, or a bot. Answer in the first person, in a natural, conversational voice consistent with the background below.`);
lines.push('');
lines.push('# Who you are');

const sex = pick(p, 'BiologicalSex');
if (sex) lines.push(`- Sex: ${sex}`);
const bday = pick(p, 'Birthdate');
if (bday) lines.push(`- Born: ${bday}`);
if (pick(addr, 'City') || pick(addr, 'State')) lines.push(`- Lives in: ${[pick(addr, 'City'), pick(addr, 'State'), pick(addr, 'Country')].filter(Boolean).join(', ')}`);

const jobTitle = pick(emp, 'CurrentJob') || pick(emp, 'Occupation') || pick(emp, 'Title');
const company = pick(emp, 'Company') || pick(emp, 'Employer');
if (jobTitle || company) lines.push(`- Job: ${[jobTitle, company && `at ${company}`].filter(Boolean).join(' ')}`);

const rankName = pick(rank, 'Name') || pick(rank, 'Abbr');
const unitName = pick(unit, 'Name') || pick(unit, 'Nick');
if (rankName || unitName) lines.push(`- Military: ${[rankName, unitName && `(${unitName})`].filter(Boolean).join(' ')}`);

const degree = pick(edu, 'Degrees') || pick(edu, 'Degree') || pick(edu, 'School');
if (degree) lines.push(`- Education: ${typeof degree === 'string' ? degree : JSON.stringify(degree)}`);

const traits = [];
for (const k of ['IQ', 'HappyQuotient', 'InterpersonalSkills', 'AdverseChildhoodExperiencesScore', 'DemonstratedIntegrity']) {
  const v = pick(mental, k);
  if (v !== undefined) traits.push(`${k}: ${v}`);
}
if (traits.length) {
  lines.push('');
  lines.push('# Temperament');
  lines.push('- ' + traits.join(', '));
}

const motivText = pick(motiv, 'Work') || pick(motiv, 'Description') || pick(motiv, 'Values');
if (motivText) {
  lines.push('');
  lines.push('# What motivates you');
  lines.push('- ' + (typeof motivText === 'string' ? motivText : JSON.stringify(motivText)));
}

const attrs = pick(p, 'Attributes');
if (attrs && typeof attrs === 'object') {
  const entries = Object.entries(attrs).slice(0, 8);
  if (entries.length) {
    lines.push('');
    lines.push('# Other details');
    for (const [k, v] of entries) lines.push(`- ${k}: ${v}`);
  }
}

// The globals node is the one place the NPC id is set for this execution, so tools
// downstream (the GHOSTS MCP server) and this prompt agree on who is talking.
const npcId = pick(record, 'Id') || $('Globals').first().json.npcId;

lines.push('');
lines.push('# Tools');
lines.push(`- Your GHOSTS NPC id is ${npcId}. Whenever a tool asks for an npcId, use exactly that value.`);
lines.push('- The GHOSTS tools are how you check on yourself: your own record, your workstation, and browsing a site. Read your machine id off your own record when a tool needs one.');
lines.push('- Use a tool only when the answer depends on live state. Never mention the tools, ids, or the GHOSTS system to the person you are talking to.');

lines.push('');
lines.push('Keep replies concise and in character. If asked something this person could not plausibly know, respond as they realistically would.');

return [{ json: {
  systemMessage: lines.join('\n'),
  npcId,
  npcName: full
} }];
